    fileprivate typealias DeclicTuple = (
        title: String,
        diagramTop: String,
        diagramBottom: String,
        step1: String,
        step2: String,
        rule: String
    )

    fileprivate struct OptionSeed {
        let badge: String
        let title: String
        let plainTitle: String
        let isCorrect: Bool
        let explanation: String
    }

    fileprivate struct ExerciseSeed {
        let formatCode: String
        let domainBadge: String
        let subBadge: String
        let prompt: String
        let plainPrompt: String
        let glossary: [(term: String, simpleMeaning: String)]
        let options: [OptionSeed]
        let cliPrefix: String?
        let expectedCLIInput: String?
        let cliBricks: [String]
        let wordBankTarget: [String]
        let wordBankAll: [String]
        let examTip: String
        let compLeftTitle: String
        let compLeftBullets: [String]
        let compRightTitle: String
        let compRightBullets: [String]
        let compRule: String

        init(
            formatCode: String = "Q_TYPE_01",
            domainBadge: String,
            subBadge: String = "SCÉNARIO PRO",
            prompt: String,
            plainPrompt: String,
            glossary: [(term: String, simpleMeaning: String)],
            options: [OptionSeed],
            cliPrefix: String? = nil,
            expectedCLIInput: String? = nil,
            cliBricks: [String] = [],
            wordBankTarget: [String] = [],
            wordBankAll: [String] = [],
            examTip: String,
            compLeftTitle: String,
            compLeftBullets: [String],
            compRightTitle: String,
            compRightBullets: [String],
            compRule: String
        ) {
            self.formatCode = formatCode
            self.domainBadge = domainBadge
            self.subBadge = subBadge
            self.prompt = prompt
            self.plainPrompt = plainPrompt
            self.glossary = glossary
            self.options = options
            self.cliPrefix = cliPrefix
            self.expectedCLIInput = expectedCLIInput
            self.cliBricks = cliBricks
            self.wordBankTarget = wordBankTarget
            self.wordBankAll = wordBankAll
            self.examTip = examTip
            self.compLeftTitle = compLeftTitle
            self.compLeftBullets = compLeftBullets
            self.compRightTitle = compRightTitle
            self.compRightBullets = compRightBullets
            self.compRule = compRule
        }

        func toExerciseItem(
            id: String,
            routeCode: String,
            mascotPose: CertiGoMascotPose,
            primaryAsset: String
        ) -> CertiGoNativeExerciseItem {
            let cleanPrompt = CertiGoDedicatedTrackQuestionBank.ensureScenarioPrompt(
                CertiGoDedicatedTrackQuestionBank.sanitizeText(prompt),
                routeCode: routeCode
            )
            let rawPlain = CertiGoDedicatedTrackQuestionBank.sanitizeText(plainPrompt)
            let cleanPlainPrompt = rawPlain == cleanPrompt
                ? "En clair pour \(routeCode) : \(rawPlain)"
                : rawPlain

            let builtOptions: [CertiGoNativeExerciseItem.OptionItem] = options.enumerated().map { idx, opt in
                let cleanTitle = CertiGoDedicatedTrackQuestionBank.sanitizeText(opt.title)
                let cleanPlainTitle = CertiGoDedicatedTrackQuestionBank.sanitizeText(opt.plainTitle)
                return CertiGoNativeExerciseItem.OptionItem(
                    id: "\(id)-opt-\(idx + 1)",
                    badge: opt.badge,
                    title: cleanTitle,
                    plainLanguageTitle: cleanPlainTitle,
                    subtitle: nil,
                    assetName: opt.isCorrect ? primaryAsset : nil,
                    isCorrect: opt.isCorrect,
                    whyWrongOrRight: CertiGoDedicatedTrackQuestionBank.sanitizeText(opt.explanation)
                )
            }
            let cleanGlossary = glossary.map {
                (
                    term: CertiGoDedicatedTrackQuestionBank.sanitizeText($0.term),
                    simpleMeaning: CertiGoDedicatedTrackQuestionBank.sanitizeText($0.simpleMeaning)
                )
            }
            return CertiGoNativeExerciseItem(
                id: id,
                formatCode: formatCode,
                domainBadge: domainBadge,
                subBadge: subBadge,
                prompt: cleanPrompt,
                plainLanguagePrompt: cleanPlainPrompt,
                jargonGlossaryBridge: cleanGlossary,
                mascotPose: mascotPose,
                options: builtOptions,
                cliPrefix: cliPrefix,
                cliSuffix: nil,
                expectedCLIInput: expectedCLIInput,
                cliSuggestionBricks: cliBricks,
                wordBankTargetTokens: wordBankTarget,
                wordBankAllBricks: wordBankAll,
                examTip: CertiGoDedicatedTrackQuestionBank.sanitizeText(examTip),
                comparisonLeftTitle: CertiGoDedicatedTrackQuestionBank.sanitizeText(compLeftTitle),
                comparisonLeftBullets: compLeftBullets.map(CertiGoDedicatedTrackQuestionBank.sanitizeText),
                comparisonRightTitle: CertiGoDedicatedTrackQuestionBank.sanitizeText(compRightTitle),
                comparisonRightBullets: compRightBullets.map(CertiGoDedicatedTrackQuestionBank.sanitizeText),
                comparisonGoldenRule: CertiGoDedicatedTrackQuestionBank.sanitizeText(compRule),
                conceptId: "\(routeCode.lowercased()):\(id)",
                conceptTitle: domainBadge,
                difficulty: formatCode == "Q_TYPE_01" ? 0.45 : 0.65
            )
        }
    }

    fileprivate struct ExamQuestionSeed {
        let domainTitle: String
        let caseStudyBadge: String
        let stem: String
        let plainStem: String
        let choices: [(badge: String, text: String, plainText: String, isCorrect: Bool)]

        func toExamQuestion(routeCode: String, number: Int) -> CertiGoNativeExamQuestion {
            let cleanStem = CertiGoDedicatedTrackQuestionBank.sanitizeText(stem)
            let rawPlainStem = CertiGoDedicatedTrackQuestionBank.sanitizeText(plainStem)
            let cleanPlainStem = rawPlainStem == cleanStem
                ? "En clair : \(rawPlainStem)"
                : rawPlainStem
            return CertiGoNativeExamQuestion(
                id: "\(routeCode)-ex-\(number)",
                number: number,
                domainTitle: CertiGoDedicatedTrackQuestionBank.sanitizeText(domainTitle),
                caseStudyBadge: caseStudyBadge,
                stem: cleanStem,
                plainLanguageStem: cleanPlainStem,
                choices: choices.map { ch in
                    CertiGoNativeExamQuestion.Choice(
                        id: ch.badge,
                        badge: ch.badge,
                        text: CertiGoDedicatedTrackQuestionBank.sanitizeText(ch.text),
                        isCorrect: ch.isCorrect,
                        plainLanguageText: CertiGoDedicatedTrackQuestionBank.sanitizeText(ch.plainText)
                    )
                }
            )
        }
    }

    fileprivate static func sanitizeText(_ text: String) -> String {
        text
            .replacingOccurrences(of: "`", with: "")
            .replacingOccurrences(of: "**", with: "")
            .replacingOccurrences(of: "\u{2014}", with: ":")
            .replacingOccurrences(of: "\u{2013}", with: "-")
    }

    fileprivate static func ensureScenarioPrompt(_ cleaned: String, routeCode: String) -> String {
        if cleaned.contains("\n") {
            return cleaned
        }
        let parts = CertiGoStructuredPromptView.splitScenarioAndQuestion(cleaned)
        if let scenario = parts.scenario, !scenario.isEmpty {
            return cleaned
        }
        return "Dans une architecture \(routeCode) en production, vous devez appliquer la bonne pratique officielle.\n\(cleaned)"
    }

    fileprivate struct TrackBlueprint {
        let code: String
        let officialTitle: String
        let shortSubtitle: String
        let vendorId: String
        let brandDisplayName: String
        let brandLogoAssetName: String
        let certificationAssetName: String
        let mascotPose: CertiGoMascotPose
        let islandAssets: [String]
        let overviewSlide1Title: String
        let overviewSlide1Body: String
        let overviewSlide1Pill: String
        let overviewSlide2Title: String
        let overviewSlide2Body: String
        let overviewSlide2Pill: String
        let overviewSlide3Body: String
        let overviewSlide3Pill: String
        let unitHeaders: [UnitHeaderBlueprint]
        let thirtySteps: [StepBlueprint]
        let unitDeclics: [DeclicTuple]
        let exerciseSeeds: [ExerciseSeed]
        let examSeeds: [ExamQuestionSeed]
    }

    private static func parseUnitAndStep(
        fromLessonId lessonId: String,
        fallbackUnit: Int,
        fallbackStepZeroBased: Int
    ) -> (unit: Int, stepZeroBased: Int) {
        let lower = lessonId.lowercased()
        var unit = fallbackUnit
        var step = fallbackStepZeroBased
        if let uRange = lower.range(of: "-u") {
            let afterU = lower[uRange.upperBound...]
            let digits = afterU.prefix(while: \.isNumber)
            if let parsedU = Int(digits), parsedU >= 1 {
                unit = min(max(parsedU, 1), 3)
            }
        }
        if let sRange = lower.range(of: "-s") {
            let afterS = lower[sRange.upperBound...]
            let digits = afterS.prefix(while: \.isNumber)
            if let parsedS = Int(digits), parsedS >= 1 {
                step = max(parsedS - 1, 0)
            }
        }
        return (unit, step)
    }

