        let code = canonicalRouteCode(rawCode)
        switch code {
        case "GH-900": return gh900Blueprint
        case "GH-300": return gh300Blueprint
        case "GH-AS": return ghASBlueprint
        case "HARVEY-LEGAL": return harveyAcademyBlueprint
        case "SC-900": return sc900Blueprint
        case "SC-300": return sc300Blueprint
        case "AI-900": return ai900Blueprint
        case "AI-102": return ai102Blueprint
        case "DP-900": return dp900Blueprint
        case "AZ-900": return az900Blueprint
        case "AZ-104": return az104Blueprint
        case "AZ-305": return az305Blueprint
        case "CLF-C02": return clfC02Blueprint
        case "SAA-C03": return saaC03Blueprint
        case "AIF-C01": return aifC01Blueprint
        case "ACE": return aceBlueprint
        case "PCA": return pcaBlueprint
        case "PDE": return pdeBlueprint
        case "AI-GEMINI": return aiGeminiBlueprint
        case "CKA": return ckaBlueprint
        case "TF-003": return tf003Blueprint
        case "CCNA": return ccnaBlueprint
        case "MS-365-COPILOT": return ms365CopilotBlueprint
        case "OPENAI-PRO": return openAIProBlueprint
        case "ANTHROPIC-CLAUDE": return anthropicClaudeBlueprint
        case "CCA-F": return ccaFBlueprint
        case "DP-100": return dp100Blueprint
        case "SC-200": return sc200Blueprint
        case "AZ-400": return az400Blueprint
        case "DVA-C02": return dvaC02Blueprint
        case "SAP-C02": return sapC02Blueprint
        case "CKAD": return ckadBlueprint
        case "CKS": return cksBlueprint
        default: return az104Blueprint
        }
    }

