        officialTitle: "GitHub Certified: GitHub Foundations",
        shortSubtitle: "Git, Pull Requests, Issues, Projects, Actions & Sécurité",
        vendorId: "github",
        brandDisplayName: "GitHub",
        brandLogoAssetName: "BrandLogos/brand-github",
        certificationAssetName: "Certifications/tech-github-foundations",
