    // MARK: - 27..33. Additional Onboarding Catalog Tracks (DP-100, SC-200, AZ-400, DVA-C02, SAP-C02, CKAD, CKS)

    private static func buildSpecializedCompanionBlueprint(
        code: String,
        officialTitle: String,
        shortSubtitle: String,
        vendorId: String,
        brandDisplayName: String,
        brandLogoAssetName: String,
        certificationAssetName: String,
        mascotPose: CertiGoMascotPose,
        islandAssets: [String],
        accentHex: String,
        lipHex: String,
        unitTitles: [(String, String, String, [String])],
        stepPrefix: [String],
        baseQuestions: [(domain: String, stem: String, plainStem: String, correct: String, plainCorrect: String, wrong1: String, wrong2: String, wrong3: String, tip: String)]
    ) -> TrackBlueprint {
        let thirtySteps: [StepBlueprint] = (0..<30).map { idx in
            let topic = stepPrefix[idx % stepPrefix.count]
            let unitNum = (idx / 10) + 1
            let stepNum = (idx % 10) + 1
            let icon = (stepNum == 4 || stepNum == 8) ? "terminal.fill" : (stepNum == 10 ? "crown.fill" : "sparkles")
            return StepBlueprint(
                "\(topic) (\(code) U\(unitNum).\(stepNum))",
                "Maîtrise pratique et réflexe d'examen \(code) sur \(topic)",
                icon
            )
        }

        let headers: [UnitHeaderBlueprint] = unitTitles.enumerated().map { idx, u in
            UnitHeaderBlueprint(
                headerTitle: "UNITÉ \(idx + 1) · \(u.0)",
                subtitle: u.1,
                accentHex: accentHex,
                lipHex: lipHex,
                memoActivity: "Valider les scénarios \(code) sur \(u.0)",
                memoKeyTopics: u.3,
                memoGoldenRule: u.2
            )
        }

        let declics: [DeclicTuple] = unitTitles.map { u in
            (
                title: "\(code) · \(u.0) : \(u.2)",
                diagramTop: "✕  Configuration manuelle non sécurisée ou hors bonnes pratiques \(brandDisplayName)",
                diagramBottom: "✓  Architecture officielle \(code) : \(u.3.joined(separator: " + "))",
                step1: "1. Applique systématiquement \(u.3[0]) et \(u.3[1])",
                step2: "2. Vérifie \(u.3[2]) avant la mise en production",
                rule: u.2
            )
        }

        let exercises: [ExerciseSeed] = baseQuestions.prefix(6).enumerated().map { idx, q in
            ExerciseSeed(
                formatCode: idx == 3 ? "Q_TYPE_04" : (idx == 4 ? "Q_TYPE_05" : "Q_TYPE_01"),
                domainBadge: "\(code) · \(q.domain.uppercased())",
                subBadge: "SCÉNARIO OFFICIEL \(code)",
                prompt: q.stem,
                plainPrompt: q.plainStem,
                glossary: [(term: q.domain, simpleMeaning: q.tip)],
                options: [
                    OptionSeed(badge: "A", title: q.correct, plainTitle: q.plainCorrect, isCorrect: true, explanation: q.tip),
                    OptionSeed(badge: "B", title: q.wrong1, plainTitle: q.wrong1, isCorrect: false, explanation: "Contraire aux bonnes pratiques \(code)."),
                    OptionSeed(badge: "C", title: q.wrong2, plainTitle: q.wrong2, isCorrect: false, explanation: "Approche non recommandée."),
                    OptionSeed(badge: "D", title: q.wrong3, plainTitle: q.wrong3, isCorrect: false, explanation: "Compromet la fiabilité ou la sécurité.")
                ],
                cliPrefix: idx >= 3 ? "\(code) :" : nil,
                expectedCLIInput: idx >= 3 ? q.correct : nil,
                cliBricks: idx >= 3 ? [q.correct, q.wrong1, q.wrong2] : [],
                wordBankTarget: idx == 4 ? [q.correct] : [],
                wordBankAll: idx == 4 ? [q.correct, q.wrong1] : [],
                examTip: q.tip,
                compLeftTitle: "Approche déconseillée",
                compLeftBullets: [q.wrong1, q.wrong2],
                compRightTitle: "Architecture \(code)",
                compRightBullets: [q.correct, q.tip],
                compRule: q.tip
            )
        }

        let exams: [ExamQuestionSeed] = (0..<12).map { idx in
            let q = baseQuestions[idx % baseQuestions.count]
            return ExamQuestionSeed(
                domainTitle: q.domain,
                caseStudyBadge: "EXAMEN \(code) · Q\(idx + 1)",
                stem: q.stem,
                plainStem: q.plainStem,
                choices: [
                    ("A", q.correct, q.plainCorrect, true),
                    ("B", q.wrong1, q.wrong1, false),
                    ("C", q.wrong2, q.wrong2, false),
                    ("D", q.wrong3, q.wrong3, false)
                ]
            )
        }

        return TrackBlueprint(
            code: code,
            officialTitle: officialTitle,
            shortSubtitle: shortSubtitle,
            vendorId: vendorId,
            brandDisplayName: brandDisplayName,
            brandLogoAssetName: brandLogoAssetName,
            certificationAssetName: certificationAssetName,
            mascotPose: mascotPose,
            islandAssets: islandAssets,
            overviewSlide1Title: "Vue globale : pourquoi passer \(code) ?",
            overviewSlide1Body: "La certification \(officialTitle) (\(code)) valide tes compétences opérationnelles sur : \(shortSubtitle).",
            overviewSlide1Pill: unitTitles.map(\.0).joined(separator: " · "),
            overviewSlide2Title: "L'architecture \(code) en 3 piliers",
            overviewSlide2Body: "1. \(unitTitles[0].0) · 2. \(unitTitles[1].0) · 3. \(unitTitles[2].0).",
            overviewSlide2Pill: unitTitles.map { $0.3.first ?? $0.0 }.joined(separator: " -> "),
            overviewSlide3Body: "• « \(unitTitles[0].3[0]) » = \(unitTitles[0].2)\n• « \(unitTitles[1].3[0]) » = \(unitTitles[1].2)\n• « \(unitTitles[2].3[0]) » = \(unitTitles[2].2)",
            overviewSlide3Pill: "\(unitTitles[0].3[0]) · \(unitTitles[1].3[0]) · \(unitTitles[2].3[0])",
            unitHeaders: headers,
            thirtySteps: thirtySteps,
            unitDeclics: declics,
            exerciseSeeds: exercises,
            examSeeds: exams
        )
    }

